effect.frag.content:
uniform float u_amount;
uniform float u_columns;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
mat2 rotation(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }
uint hash(uint x) { x ^= x >> 16; x *= 2146121005u; x ^= x >> 15; x *= 2221713035u; return x ^ (x >> 16); }
float randomValue(vec2 p) { return float(hash(uint(p.x) + hash(uint(p.y) + uint(u_seed) * 31u + 17u)) >> 8) / 16777216.0; }
vec4 over(vec4 front, vec4 back) { return front + back * (1.0 - front.a); }
void main() {
  vec4 color = vec4(0.0);
  float fall = u_progress * u_progress * (0.4 + u_amount * 2.0);
  for (int y = 0; y < 12; y++) for (int x = 0; x < 12; x++) {
    if (float(x) >= u_columns || float(y) >= u_columns) continue;
    vec2 cell = vec2(float(x), float(y)), original = (cell + 0.5) / u_columns;
    vec2 center = rotation(0.22) * ((original - 0.5) * 0.8) + 0.5;
    float floorHeight = 0.04 + original.y * 0.14 + randomValue(cell) * 0.03;
    center.y = max(floorHeight, center.y - fall * (0.8 + randomValue(cell) * 0.4));
    vec2 local = rotation(-0.22) * (v_uv - center) / 0.8;
    vec2 uv = original + local;
    if (all(greaterThanEqual(uv, cell / u_columns)) && all(lessThan(uv, (cell + 1.0) / u_columns))) color = over(sourceAt(uv), color);
  }
  fragColor = color;
}
